function solve(precos) {
    const n = precos.length;
    if (n <= 1) return 0;

    // Forward pass: max profit with 1 transaction in prices[0..i]
    let minPrice = precos[0];
    const forward = new Array(n);
    forward[0] = 0;
    for (let i = 1; i < n; i++) {
        minPrice = Math.min(minPrice, precos[i]);
        forward[i] = Math.max(forward[i - 1], precos[i] - minPrice);
    }

    // Backward pass: max profit with 1 transaction in prices[i..n-1]
    let maxPrice = precos[n - 1];
    const backward = new Array(n);
    backward[n - 1] = 0;
    for (let i = n - 2; i >= 0; i--) {
        maxPrice = Math.max(maxPrice, precos[i]);
        backward[i] = Math.max(backward[i + 1], maxPrice - precos[i]);
    }

    // Combine: best profit = forward[i] + backward[i] for some i
    let maxProfit = 0;
    for (let i = 0; i < n; i++) {
        maxProfit = Math.max(maxProfit, forward[i] + backward[i]);
    }

    return maxProfit;
}
